import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxButton, JxInputField, JxToastViewport, useJxToastQueue } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const toasts = useJxToastQueue();
  const [email, setEmail] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const invalid = submitted && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitted(true);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return;

    toasts.push({
      title: 'Готово',
      message: `Письмо с подтверждением отправлено на ${email}`,
      variant: 'success',
    });
    setEmail('');
    setSubmitted(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{ display: 'grid', gap: '16px', maxWidth: '360px' }}
    >
      <JxInputField
        label="Электронная почта"
        type="email"
        name="email"
        required
        autoComplete="email"
        placeholder="name@example.com"
        value={email}
        onChange={(event) => {
          setEmail(event.target.value);
          setSubmitted(false);
        }}
        helperText="Раз в неделю, без спама"
        errorText={invalid ? 'Укажите адрес с символом @' : undefined}
      />
      <JxButton type="submit" variant="primary">
        Подписаться
      </JxButton>
      <JxToastViewport items={toasts.items} onDismiss={toasts.dismiss} position="top-right" />
    </form>
  );
}

